package com.demo.employee;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/employees") public class EmployeeController{private final EmployeeService s;public EmployeeController(EmployeeService s){this.s=s;}@GetMapping public List<Employee> all(){return s.all();}@PostMapping public Employee add(@RequestBody Employee e){return s.add(e);}}